import React from 'react';
import styled from 'styled-components';

const HeaderBar = styled.header`
  position: fixed;
  top: 0;
  left: 0;
  width: 100vw;
  max-width: 100vw;
  box-sizing: border-box;
  padding: 1.5rem 2.5rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: ${({ theme }) => theme.bg};
  color: ${({ theme }) => theme.text};
  z-index: 1000;
  border-bottom: 1px solid rgba(255,255,255,0.04);
`;

const Name = styled.a`
  font-size: 2rem;
  font-weight: 900;
  letter-spacing: -2px;
  color: inherit;
  text-decoration: none;
  cursor: pointer;
`;

const Nav = styled.nav`
  display: flex;
  align-items: center;
  gap: 2rem;
`;

const NavLink = styled.a`
  font-size: 1.1rem;
  font-weight: 400;
  color: ${({ theme }) => theme.text};
  opacity: 0.85;
  text-decoration: none;
  transition: opacity 0.18s;
  &:hover, &:focus {
    opacity: 1;
  }
`;
const Switch = styled.button`
  background: transparent;
  color: ${({ theme }) => theme.bg === '#fff' ? '#000' : '#fff'};
  border-radius: 100px;
  padding: 0.5rem 0.5rem;
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: 0.5rem;
  border: none;
  transition: color 0.2s;
  margin-left: 5.5rem;
  &:hover, &:focus {
    color: ${({ theme }) => theme.bg === '#fff' ? '#444' : '#fff'};
  }
`;

const ContactBtn = styled.a`
  padding: 1rem 2rem;
  border-radius: 100px;
  border: 1px solid ${({ theme }) => theme.text};
  background: ${({ theme }) => theme.bg === '#fff' ? '#000' : '#fff'};
  color: ${({ theme }) => theme.bg === '#fff' ? '#fff' : '#000'};
  font-weight: 500;
  font-size: 1rem;
  text-decoration: none;
  transition: background 0.2s, color 0.2s;
  cursor: pointer;
  &:hover, &:focus {
    background: ${({ theme }) => theme.bg === '#fff' ? '#222' : '#eee'};
    color: ${({ theme }) => theme.bg === '#fff' ? '#fff' : '#000'};
    text-decoration: none;
  }
`;





function Header({ mode, setMode }) {
  // Smooth scroll handler
  const handleNav = (e, target) => {
    e.preventDefault();
    if (target === 'bottom') {
      window.scrollTo({ top: document.body.scrollHeight, behavior: 'smooth' });
    } else {
      const el = document.getElementById(target);
      if (el) {
        el.scrollIntoView({ behavior: 'smooth' });
      }
    }
  };

  return (
    <HeaderBar>
      <Name href="#" onClick={e => handleNav(e, 'hero')}>Valdrin Shala</Name>
      <Nav>
        <NavLink href="#" onClick={e => handleNav(e, 'hero')}>Home</NavLink>
        <NavLink href="#" onClick={e => handleNav(e, 'projects')}>Work</NavLink>
        <NavLink href="#" onClick={e => handleNav(e, 'about')}>About</NavLink>
        <Switch onClick={() => setMode(mode === 'dark' ? 'light' : 'dark')} aria-label="Toggle dark mode">
          {/* You can add an icon here if desired, e.g. a moon/sun SVG */}
          {mode === 'dark' ? '🌙' : '☀️'}
        </Switch>
        <ContactBtn href="#contact">Let's Talk</ContactBtn>
      </Nav>
    </HeaderBar>
  );
}

export default Header;
